// Parse explained search parameters
const query = $json.query || $json.body?.query || '';
const limit = $json.limit || $json.body?.limit || 5;
const minScore = $json.min_score || $json.body?.min_score || 0.7;

if (!query) {
  throw new Error('query is required');
}

return {
  json: {
    query,
    limit,
    min_score: minScore
  }
};

// Format explained search results with score breakdown
const response = $json;

if (response.status === 'error') {
  return {
    json: {
      success: false,
      error: response.message || 'Explained search error',
      results: []
    }
  };
}

const results = (response.results || []).map(result => ({
  document_id: result.document_id,
  document_name: result.metadata?.document_name || result.document_name,
  document_type: result.metadata?.document_type || 'unknown',
  department: result.metadata?.department || 'unknown',

  // Content
  content: result.text || result.content,
  content_preview: (result.text || result.content || '').substring(0, 200) + '...',

  // Scores
  relevance_score: result.score || 0,
  quality_score: result.metadata?.quality_score || 0,

  // Score explanation breakdown
  explanation: {
    semantic_score: result.explanation?.semantic_score || 0,
    quality_boost: result.explanation?.quality_boost || 0,
    recency_factor: result.explanation?.recency_factor || 0,
    tf_boost: result.explanation?.tf_boost || 0,
    matching_terms: result.explanation?.matching_terms || [],
    formula: result.explanation?.formula || 'semantic * (1 + quality + recency + tf)',
    components: {
      base_semantic: result.explanation?.semantic_score || 0,
      quality_multiplier: result.explanation?.quality_boost || 0,
      recency_multiplier: result.explanation?.recency_factor || 0,
      tf_multiplier: result.explanation?.tf_boost || 0
    }
  },

  // Context
  chunk_index: result.chunk_key || result.metadata?.chunk_index,
  document_url: result.metadata?.document_url || null,

  // Additional metadata
  processing_profile: result.metadata?.processing_profile || 'railway',
  document_date: result.metadata?.document_date || null,
  version: result.metadata?.version || null
}));

return {
  json: {
    success: true,
    results,
    metadata: {
      query: response.metadata?.query || '',
      total_results: results.length,
      search_type: 'explained',
      min_score_applied: response.metadata?.min_score || 0.7,
      explanation_available: true
    }
  }
};
